"""One native path sweep for ordinary and divided editable carriageways.

The first repeat builds all actual filleted centerlines. The second samples
them into direct quad grids. Divided members retain their own independently
edited centerlines, but use a common longitudinal count; one owner fills the
separator between the exact inner member edges with another direct quad grid.
No triangles, surface vertices, or sampled curve coordinates are made in Python.
"""
import bpy

from .path_surface_nodes import _Nodes
from . import unified_curve_nodes

NAME = 'Prochitecture Streets / Universal native Section surfaces v1'
REVISION = 1


def _positive_quads(g, mesh, index, pos):
    """Check all four planar corner Jacobians without triangulating a face."""
    corners = []
    for corner in range(4):
        c = g.node('GeometryNodeCornersOfFace', 'Quad corner '+str(corner))
        g.set(index, c.inputs['Face Index'])
        c.inputs['Sort Index'].default_value = corner
        v = g.node('GeometryNodeVertexOfCorner', 'Quad vertex '+str(corner))
        g.set(c.outputs['Corner Index'], v.inputs['Corner Index'])
        corners.append(g.sample(mesh, pos, v.outputs['Vertex Index'], 'FLOAT_VECTOR'))
    checks = []
    for corner in range(4):
        a, b, c = [corners[(corner+j)%4] for j in range(3)]
        cross = g.vector('CROSS_PRODUCT', g.vector('SUBTRACT', b, a), g.vector('SUBTRACT', c, b))
        checks.append(g.compare(g.component(cross, 'Z'), 1e-9, 'GREATER_THAN'))
    return g.stat(mesh, g.all(*checks), 'FACE')


def build():
    existing = bpy.data.node_groups.get(NAME)
    if existing:
        if existing.get('revision') != REVISION:
            raise ValueError('Unexpected universal Section surface revision')
        return existing
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree')
    g = _Nodes(tree)
    for name, kind, default in [
        ('Sources', 'NodeSocketGeometry', None),
        ('Paths', 'NodeSocketGeometry', None),
        ('Mouths', 'NodeSocketGeometry', None),
        ('Radial Samples', 'NodeSocketInt', 8),
        ('Cell Size', 'NodeSocketFloat', .7),
        ('Mesh Resolution', 'NodeSocketInt', 1),
        ('Height Exaggeration', 'NodeSocketFloat', 10.),
        ('Material', 'NodeSocketMaterial', None),
        ('Grass Material', 'NodeSocketMaterial', None),
    ]:
        socket = tree.interface.new_socket(name=name, in_out='INPUT', socket_type=kind)
        if default is not None:
            socket.default_value = default
    tree.interface.new_socket(name='Geometry', in_out='OUTPUT', socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Valid', in_out='OUTPUT', socket_type='NodeSocketBool')
    inp = g.node('NodeGroupInput', 'Actual source Sections and mouth frames')
    out = g.node('NodeGroupOutput', 'Universal profiled path surfaces')
    sources, paths, mouths = [inp.outputs[n] for n in ('Sources', 'Paths', 'Mouths')]
    index = g.node('GeometryNodeInputIndex', 'Domain sample index').outputs[0]
    pos = g.node('GeometryNodeInputPosition', 'Domain position').outputs[0]
    count = g.node('GeometryNodeAttributeDomainSize', 'One complete Section per path record')
    count.component = 'MESH'
    g.set(paths, count.inputs['Geometry'])
    path_count = count.outputs['Point Count']

    # Building every curve first lets either member look up its partner length
    # and coordinate field without requiring synchronized source control points.
    ci = g.node('GeometryNodeRepeatInput', 'Build every actual trimmed curve')
    co = g.node('GeometryNodeRepeatOutput', 'Ordered curves with sweep metadata')
    co.repeat_items.clear()
    co.repeat_items.new('GEOMETRY', 'Curves')
    co.repeat_items.new('BOOLEAN', 'Valid')
    ci.pair_with_output(co)
    ci.inputs['Valid'].default_value = True
    g.set(path_count, ci.inputs['Iterations'])
    curve, valid = unified_curve_nodes.construct(
        g, sources, paths, mouths, ci.outputs['Iteration'], inp, index, pos)
    join = g.node('GeometryNodeJoinGeometry', 'Append one curve in path-record order')
    g.set(ci.outputs['Curves'], join.inputs['Geometry'])
    g.set(curve, join.inputs['Geometry'])
    g.set(join.outputs['Geometry'], co.inputs['Curves'])
    g.set(g.all(ci.outputs['Valid'], valid), co.inputs['Valid'])
    ordered = g.node('GeometryNodeSortElements', 'Stable path-record order for partner lookup')
    ordered.domain = 'CURVE'
    g.set(co.outputs['Curves'], ordered.inputs['Geometry'])
    g.set(g.named('st_sweep_order', 'INT'), ordered.inputs['Sort Weight'])
    curves = ordered.outputs['Geometry']

    ri = g.node('GeometryNodeRepeatInput', 'Sweep each complete Section once')
    ro = g.node('GeometryNodeRepeatOutput', 'Accumulate pavement and separator quads')
    ro.repeat_items.clear()
    ro.repeat_items.new('GEOMETRY', 'Surfaces')
    ro.repeat_items.new('BOOLEAN', 'Valid')
    ri.pair_with_output(ro)
    g.set(co.outputs['Valid'], ri.inputs['Valid'])
    g.set(path_count, ri.inputs['Iterations'])
    iteration = ri.outputs['Iteration']

    def meta(name, kind='FLOAT', at=None):
        return g.sample(curves, g.named('st_sweep_'+name, kind),
                        iteration if at is None else at, kind, 'CURVE')

    divided = meta('divided', 'BOOLEAN')
    partner = meta('partner', 'INT')
    reversed_pair = meta('reversed', 'BOOLEAN')
    make_grass = meta('make_grass', 'BOOLEAN')
    inner_u = meta('inner_u')
    bundle = meta('bundle_id', 'INT')
    width, offset, rise, datum, length = [meta(n) for n in ('width', 'offset', 'rise', 'datum', 'length')]
    factor = g.math('POWER', 2., g.math('SUBTRACT', inp.outputs['Mesh Resolution'], 1.))
    transverse = g.math('MULTIPLY', inp.outputs['Radial Samples'],
                        g.switch(divided, 2., .75))
    transverse = g.math('MULTIPLY', transverse, factor)
    target_cell = g.math('DIVIDE', inp.outputs['Cell Size'], factor)
    longest = g.switch(divided, length, g.math('MAXIMUM', length, meta('length', at=partner)))
    intervals = g.math('MAXIMUM', 1., g.math('CEIL', g.math('DIVIDE', longest, target_cell)))
    ny = g.math('ADD', intervals, 1.)

    paired_ok = g.all(
        g.compare(partner, 0, 'GREATER_EQUAL', 'INT'),
        g.compare(partner, path_count, 'LESS_THAN', 'INT'),
        g.compare(partner, iteration, 'NOT_EQUAL', 'INT'),
        meta('divided', 'BOOLEAN', partner),
        g.compare(meta('partner', 'INT', partner), iteration, 'EQUAL', 'INT'),
        g.compare(meta('reversed', 'BOOLEAN', partner), reversed_pair, 'EQUAL', 'INT'),
        g.compare(meta('make_grass', 'BOOLEAN', partner), make_grass, 'NOT_EQUAL', 'INT'),
        g.compare(meta('bundle_id', 'INT', partner), bundle, 'EQUAL', 'INT'),
        g.close(meta('rise', at=partner), rise),
        g.close(meta('datum', at=partner), datum))
    checks = [g.switch(divided, True, paired_ok, 'BOOLEAN')]

    def frame(at, s):
        sample = g.node('GeometryNodeSampleCurve', 'Arc-length sample of actual member curve')
        sample.mode = 'FACTOR'
        sample.use_all_curves = False
        g.set(curves, sample.inputs['Curves'])
        g.set(at, sample.inputs['Curve Index'])
        g.set(s, sample.inputs['Factor'])
        at_start, at_end = g.close(s, 0., 1e-7), g.close(s, 1., 1e-7)
        tangent = g.switch(at_start, sample.outputs['Tangent'], meta('start_tangent', 'FLOAT_VECTOR', at), 'VECTOR')
        tangent = g.switch(at_end, tangent, meta('end_tangent', 'FLOAT_VECTOR', at), 'VECTOR')
        center = g.switch(at_start, sample.outputs['Position'], meta('start', 'FLOAT_VECTOR', at), 'VECTOR')
        center = g.switch(at_end, center, meta('end', 'FLOAT_VECTOR', at), 'VECTOR')
        return center, tangent

    grid = g.node('GeometryNodeMeshGrid', 'Direct carriageway quads by width and arc length')
    g.set(g.math('ADD', transverse, 1.), grid.inputs['Vertices X'])
    g.set(ny, grid.inputs['Vertices Y'])
    u = g.math('DIVIDE', g.math('FLOOR', g.math('DIVIDE', index, ny)), transverse)
    s = g.math('DIVIDE', g.math('MODULO', index, ny), intervals)
    center, tangent = frame(iteration, s)
    across = g.math('ADD', offset, g.math('MULTIPLY', width, g.math('SUBTRACT', u, .5)))
    xy = g.vector('ADD', center, g.vector('SCALE', g.right(tangent), across))
    whole_crown = g.math('MULTIPLY', g.math('MULTIPLY', 4., u), g.math('SUBTRACT', 1., u))
    half_crown = g.math('SUBTRACT', 1., g.math('POWER', g.math('SUBTRACT', u, inner_u), 2.))
    crown = g.switch(divided, whole_crown, half_crown)
    height = g.math('ADD', datum, g.math('MULTIPLY', inp.outputs['Height Exaggeration'], g.math('MULTIPLY', rise, crown)))
    surface_pos = g.xyz(g.component(xy, 'X'), g.component(xy, 'Y'), height)
    setpos = g.node('GeometryNodeSetPosition', 'Preserve complete ordinary or half-crown profile')
    g.set(grid.outputs['Mesh'], setpos.inputs['Geometry'])
    g.set(surface_pos, setpos.inputs['Position'])
    mesh = setpos.outputs['Geometry']
    mesh = g.store(mesh, 'st_path_u', u)
    mesh = g.store(mesh, 'st_path_s', s)
    mesh = g.store(mesh, 'st_path_id', meta('id', 'INT'), 'INT', 'FACE')
    mesh = g.store(mesh, 'st_bundle_id', bundle, 'INT', 'FACE')
    mesh = g.store(mesh, 'st_component_kind', 0, 'INT', 'FACE')
    checks.append(_positive_quads(g, mesh, index, pos))
    material = g.node('GeometryNodeSetMaterial', 'Pavement material')
    g.set(mesh, material.inputs['Geometry'])
    g.set(inp.outputs['Material'], material.inputs['Material'])
    pavement = material.outputs['Geometry']

    # Both boundaries use their member's own physical inner edge. Equal rows
    # and exact boundary samples allow Merge by Distance to weld all three grids.
    grass_segments = g.math('MULTIPLY', g.math('MULTIPLY', .5, inp.outputs['Radial Samples']), factor)
    grass_grid = g.node('GeometryNodeMeshGrid', 'Direct separator quads between exact inner edges')
    g.set(g.math('ADD', grass_segments, 1.), grass_grid.inputs['Vertices X'])
    g.set(ny, grass_grid.inputs['Vertices Y'])
    grass_u = g.math('DIVIDE', g.math('FLOOR', g.math('DIVIDE', index, ny)), grass_segments)
    grass_s = s

    def inner_edge(at, along):
        c, t = frame(at, along)
        across = g.math('ADD', meta('offset', at=at),
                        g.math('MULTIPLY', meta('width', at=at), g.math('SUBTRACT', meta('inner_u', at=at), .5)))
        return g.vector('ADD', c, g.vector('SCALE', g.right(t), across))

    owner_edge = inner_edge(iteration, grass_s)
    partner_s = g.switch(reversed_pair, grass_s, g.math('SUBTRACT', 1., grass_s))
    partner_edge = inner_edge(partner, partner_s)
    blend_u = g.switch(g.compare(inner_u, .5, 'GREATER_THAN'),
                       g.math('SUBTRACT', 1., grass_u), grass_u)
    grass_xy = g.vector('ADD', owner_edge,
                        g.vector('SCALE', g.vector('SUBTRACT', partner_edge, owner_edge), blend_u))
    grass_height = g.math('ADD', datum, g.math('MULTIPLY', inp.outputs['Height Exaggeration'], rise))
    grass_position = g.xyz(g.component(grass_xy, 'X'), g.component(grass_xy, 'Y'), grass_height)
    grass_pos = g.node('GeometryNodeSetPosition', 'Crown-height separator plateau')
    g.set(grass_grid.outputs['Mesh'], grass_pos.inputs['Geometry'])
    g.set(grass_position, grass_pos.inputs['Position'])
    grass = grass_pos.outputs['Geometry']
    grass = g.store(grass, 'st_path_u', grass_u)
    grass = g.store(grass, 'st_path_s', grass_s)
    grass = g.store(grass, 'st_path_id', -2, 'INT', 'FACE')
    grass = g.store(grass, 'st_bundle_id', bundle, 'INT', 'FACE')
    grass = g.store(grass, 'st_component_kind', 1, 'INT', 'FACE')
    grass_ok = _positive_quads(g, grass, index, pos)
    owns_grass = g.all(divided, make_grass)
    checks.append(g.switch(owns_grass, True, grass_ok, 'BOOLEAN'))
    grass_mat = g.node('GeometryNodeSetMaterial', 'Separator grass material')
    g.set(grass, grass_mat.inputs['Geometry'])
    g.set(inp.outputs['Grass Material'], grass_mat.inputs['Material'])
    grass = g.switch(owns_grass, None, grass_mat.outputs['Geometry'], 'GEOMETRY', 'One owner per separator')
    join = g.node('GeometryNodeJoinGeometry', 'Append this pavement and its owned separator')
    for geometry in (ri.outputs['Surfaces'], pavement, grass):
        g.set(geometry, join.inputs['Geometry'])
    g.set(join.outputs['Geometry'], ro.inputs['Surfaces'])
    g.set(g.all(ri.outputs['Valid'], *checks), ro.inputs['Valid'])
    smooth = g.node('GeometryNodeSetShadeSmooth', 'Smooth profile and bend shading')
    g.set(ro.outputs['Surfaces'], smooth.inputs['Geometry'])
    gated = g.switch(ro.outputs['Valid'], None, smooth.outputs['Geometry'], 'GEOMETRY', 'Reject incompatible path geometry')
    g.set(gated, out.inputs['Geometry'])
    g.set(ro.outputs['Valid'], out.inputs['Valid'])
    tree['revision'] = REVISION
    tree['construction'] = 'Native actual Section curves; independently editable divided members; common arc-length rows; direct pavement and separator quads'
    return tree
